    function renderUltimate(){const panel=document.querySelector('#ultimate-panel');if(!panel)return;panel.classList.remove('ultimate-ready');if(!ultimateState){const setup=battlePhase==='setup',settingLock=ultimateSettingLockReason();panel.innerHTML='<div class="setting-title"><strong>궁극기 세팅</strong><span>'+ultimateQuotaLabel()+'</span></div><button class="ultimate-slot-empty ultimate-cta '+(ultimateArmed?'armed':'')+'" onclick="armUltimateSetting()" '+(setup&&!ultimateUsed&&!settingLock?'':'disabled')+' aria-pressed="'+ultimateArmed+'"><span class="cta-main">'+(ultimateUsed?'궁극기 '+ULTIMATE_MAX_USES+'회 모두 사용':settingLock?settingLock:ultimateArmed?'궁극기 Slot 활성화<br>궁극 캐릭터를 선택해주세요':'✦ 궁극기 세팅하기')+'</span><small>'+(ultimateUsed?'사용한 궁극기 카드는 묘지로 이동했습니다':settingLock?ultimateSettingLockDetail():ultimateArmed?'클릭한 캐릭터가 즉시 궁극기로 장착됩니다 · 이 버튼을 다시 누르면 취소':setup?'버튼을 누르고 캐릭터를 클릭하거나, 카드를 여기로 드래그하세요':'전투 중에는 세팅할 수 없습니다')+'</small></button>';renderFieldUltimateAction();return;}const reason=ultimateLockReason(),ready=!reason;panel.classList.toggle('ultimate-ready',ready);panel.innerHTML='<div class="setting-title"><strong>궁극기 세팅</strong><span>'+ultimateQuotaLabel()+'</span></div><div class="ultimate-slot"><img src="'+ultimateState.art+'" alt=""><div><h4>'+ultimateState.title+'</h4><p>'+ultimateState.description+'<br>마나 '+ultimateState.cost+' · '+ultimateState.condition+'<br><b>'+(ready?'전장 중앙에서 발동 가능':reason)+'</b></p></div></div>';renderFieldUltimateAction();}
