    function renderMagicSlots(){for(let slot=0;slot<MAGIC_SLOT_KINDS.length;slot++){const rack=document.querySelector('#magic-slot-'+slot),magic=magicInSlot(slot);if(!rack)continue;const pending=magic&&turnNumber<magic.readyTurn,state=!magic?'':magic.kind==='reaction'?(magic.effect==='global-destroy'?(pending?'발동까지 '+(magic.readyTurn-turnNumber)+'턴':'발동 대기'):pending?'다음 필드부터 조건 감지':'조건 감지 중'):(magic.fireTurn>turnNumber?'발동까지 '+(magic.fireTurn-turnNumber)+'턴':'턴 종료 시 자동 발동');rack.classList.toggle('ready',Boolean(magic));rack.classList.toggle('trap-slot',MAGIC_SLOT_KINDS[slot]==='reaction');rack.innerHTML=magic?'<strong>'+magicSlotLabel(slot)+' · '+magic.name+'</strong><span>✦ '+state+'</span>':'<strong>'+magicSlotLabel(slot)+' · 비어 있음</strong><span class="slot-empty">'+(MAGIC_SLOT_KINDS[slot]==='reaction'?'함정카드 대기':'마법카드 대기')+'</span>';}}
