    const MAGIC_REVEAL_MS=1500,MAGIC_EFFECT_SETTLE_MS=900,MAGIC_SEQUENCE_GAP_MS=250;
    function activateSetMagic(index,automatic=false){/* automatic이면 index는 setMagicCards 순번, 슬롯 클릭이면 화면 슬롯 번호다 */const magic=automatic?setMagicCards[index]:magicInSlot(index);if(!magic)return Promise.resolve(false);if(!automatic){writeLog('<strong>'+magic.name+'</strong>은(는) '+(magic.kind==='reaction'?'다음 필드부터 조건 충족 시 자동 발동합니다.':'턴을 종료하면 바로 자동 발동합니다.'));return Promise.resolve(false);}if(magic.kind==='reaction'||turnNumber<magic.readyTurn)return Promise.resolve(false);setMagicCards.splice(index,1);renderMagicSlots();const card=magic.card,effectText=card.querySelector('p').textContent,art=cardArtwork(card),global=document.createElement('div');global.className='global-spell owner-player';global.innerHTML='<div class="global-spell-card"><span class="owner-tag">▲ 내 마법</span><small>MAGIC CAST · '+card.querySelector('.type').textContent.replace('✦ ','')+'</small><div class="global-icon">'+(art?'<img src="'+art+'" alt="'+magic.name+'">':card.querySelector('.art').textContent)+'</div><h2>'+magic.name+'</h2><p>효과 발동 준비 중…</p></div>';return new Promise(resolve=>{fxPresent('magic:'+magic.name,()=>{document.body.appendChild(global);if(typeof syncFieldFrame==='function')syncFieldFrame();showEffectNarration('magic',magic.name,effectText,MAGIC_REVEAL_MS);return ()=>global.remove();},{priority:FX_PRIORITY.magic,hold:MAGIC_REVEAL_MS}).then(()=>castSpell(card)).then(()=>{writeLog('<strong>'+magic.name+'</strong>이(가) 발동했습니다.');setTimeout(()=>resolve(true),MAGIC_EFFECT_SETTLE_MS);});});}
