    async function resolveEndTurnMagic(button){const due=setMagicCards.filter(magic=>magic.kind==='active'&&(magic.fireTurn??turnNumber)<=turnNumber);if(!due.length)return 0;setBattlePhase('magic-resolving');if(button)button.textContent='마법 발동 중…';for(const magic of due){magic.readyTurn=turnNumber;const index=setMagicCards.indexOf(magic);if(index>=0)await activateSetMagic(index,true);if(resultPending)return due.length;await new Promise(resolve=>setTimeout(resolve,MAGIC_SEQUENCE_GAP_MS));}renderMagicSlots();return due.length;}
