        atkNode.textContent='⚔ '+attack;hpNode.textContent='♥ '+health;target.dataset.maxHp=String(Number(target.dataset.maxHp||health-5)+5);target.dataset.shield='true';target.dataset.lastStand='true';target.classList.remove('exhausted');target.style.boxShadow='0 0 0 2.7px #79cfff,0 0 30.6px #4a9ff2,0 0 63px #60d9ff66';
        showEffectNarration('trap',trap.name,'아군 1명 vs 적군 '+enemies.length+'명 · 유일한 하수인에게 +5/+5, 보호막, 공격 기회 부여',2600);showSkillEffect('shield',target,trap.name+' · +5/+5');writeLog('<strong>'+trap.name+'</strong>이(가) 발동해 '+target.querySelector('h4').textContent+'이 +5/+5, 보호막과 공격 기회를 얻었습니다.');updateSynergyHud();return {prevented:false,buffed:true};
