    const resolveEnemySpellEffect=resolveEnemySpell;
    const ENEMY_MAGIC_REVEAL_MS=1500,ENEMY_MAGIC_EFFECT_SETTLE_MS=900;
    function showEnemyMagicActivation(card,onResolve){const art=card.art||card.image||'',effectText=runtimeRulesText(card.effect,cardDefByArt.get(card.art)),global=document.createElement('div');global.className='global-spell enemy-magic-activation owner-enemy';global.setAttribute('role','status');global.setAttribute('aria-label','상대 마법 '+card.name+' 발동');global.innerHTML='<div class="global-spell-card"><span class="owner-tag">▼ 상대의 마법</span><small>ENEMY MAGIC ACTIVATION</small><div class="global-icon">'+(art?'<img src="'+art+'" alt="'+card.name+'">':'✦')+'</div><h2>'+card.name+'</h2><p>효과 발동 준비 중…</p></div>';return new Promise(resolve=>{fxPresent('enemy-magic:'+card.name,()=>{document.body.appendChild(global);if(typeof syncFieldFrame==='function')syncFieldFrame();showEffectNarration('magic','상대 · '+card.name,effectText,ENEMY_MAGIC_REVEAL_MS);combatPresentationUntil=Math.max(combatPresentationUntil,performance.now()+ENEMY_MAGIC_REVEAL_MS+ENEMY_MAGIC_EFFECT_SETTLE_MS);return ()=>global.remove();},{priority:FX_PRIORITY.magic,hold:ENEMY_MAGIC_REVEAL_MS}).then(()=>{onResolve();setTimeout(resolve,ENEMY_MAGIC_EFFECT_SETTLE_MS);});});}
    resolveEnemySpell=function(card){return showEnemyMagicActivation(card,()=>resolveEnemySpellEffect(card));};
    async function resolveEnemySetMagic(){const due=enemySetMagic.filter(card=>!card.trap&&(card.fireAt??0)<=ultimateLedger.enemy.turns);for(const card of due){enemySetMagic.splice(enemySetMagic.indexOf(card),1);await resolveEnemySpell(card);await new Promise(resolve=>setTimeout(resolve,MAGIC_SEQUENCE_GAP_MS));}return due.length;}
    function triggerEnemyTrap(event,context={}){const enemyUnits=[...document.querySelectorAll('.arena .lane:first-child > .unit:not([data-destroyed="true"])')],playerUnits=[...document.querySelectorAll('.summon-zone .unit:not([data-destroyed="true"])')],index=enemySetMagic.findIndex(card=>card.trap&&card.readyTurn<=turnNumber&&((event==='player_summon'&&/^(ambush-mine|negate-summon|ember-snare|swamp-bind)$/.test(card.effect))||(event==='enemy_hero_attacked'&&/^(counter-current|steel-guard)$/.test(card.effect))||((event==='field_state'||event==='player_summon')&&((card.effect==='last-stand'&&enemyUnits.length===1&&playerUnits.length>=3)||(card.effect==='rally-cry'&&enemyUnits.length>=1&&playerUnits.length-enemyUnits.length>=3)))||(event==='field_state'&&card.effect==='global-destroy')));if(index<0)return {prevented:false};const trap=enemySetMagic.splice(index,1)[0];showTrapActivation(trap,'enemy');showEffectNarration('trap','상대 · '+trap.name,runtimeRulesText(trap.effect,cardDefByArt.get(trap.art)),2300);writeLog('<strong>상대 함정 발동:</strong> '+trap.name);if(trap.effect==='global-destroy'){setTimeout(()=>enemyDamageUnits([...playerUnits,...enemyUnits],9999,'neutral'),TRAP_EFFECT_LEAD_MS);return {prevented:false};}if(trap.effect==='negate-summon'){if(context.unit){const doomed=context.unit;doomed.dataset.destroyed='true';setTimeout(()=>{if(!doomed.isConnected)return;const gone=sendCardTo(doomed,'graveyard',doomed.querySelector('h4')?.textContent||'');doomed.style.visibility='hidden';setTimeout(()=>doomed.remove(),Math.max(1,gone));},TRAP_EFFECT_LEAD_MS);}summonDenyRecoil(trap.name);return {prevented:true};}if(trap.effect==='ambush-mine'){enemyDamageUnits([context.unit],4,'earth');return {prevented:false};}if(trap.effect==='counter-current'){enemyDamageUnits([context.attacker],3,'water');return {prevented:true};}if(trap.effect==='last-stand'){const unit=enemyUnits[0],stats=unit.querySelectorAll('.stats span');stats[0].textContent='⚔ '+(unitStat(unit,0)+5);stats[1].textContent='♥ '+(unitStat(unit,1)+5);unit.dataset.shield='true';unit.classList.remove('exhausted');return {prevented:false};}if(trap.effect==='ember-snare'){enemyDamageUnits([context.unit],2,'fire');return {prevented:false};}if(trap.effect==='swamp-bind'){snareUnit(context.unit);showSkillEffect('shield',context.unit,'늪의 속박');return {prevented:false};}if(trap.effect==='steel-guard'){const hud=document.querySelector('.duel-hud .enemy'),bar=hud?.querySelector('.health i'),incoming=Math.max(0,Number(context.damage)||0),taken=0/* 2026-11-09: 첫 공격 완전 차단 */;if(taken&&hud){impact(hud.querySelector('.avatar'),taken,'neutral');enemyHp=Math.max(0,enemyHp-taken);if(bar){bar.style.width=(enemyHp/HERO_MAX_HP*100)+'%';bar.parentElement.setAttribute('aria-label','상대 체력 '+enemyHp+' / '+HERO_MAX_HP);}}writeLog('<strong>상대 함정 '+trap.name+'</strong>이(가) 소환사 피해를 '+incoming+'에서 '+taken+'(으)로 줄였습니다. 상대 남은 체력 '+enemyHp);if(enemyHp<=0)finish(true,'상대 소환사의 체력을 0으로 만들었습니다.');return {prevented:true,logged:true};}if(trap.effect==='rally-cry'){enemyUnits.forEach(unit=>{const stats=unit.querySelectorAll('.stats span');stats[0].textContent='⚔ '+(unitStat(unit,0)+2);});return {prevented:false};}return {prevented:false};}
    function enemyUltimateSpec(data){const base=baseCardStatsByArt(data.art),element=data.el,baseAttack=base?base.atk:Number(data.atk)||0,baseHp=base?base.hp:Math.max(1,Number(data.hp)||1);return {...data,element,personality:cardDefByArt.get(data.art)?.aura||'',attack:baseAttack,baseAttack,baseHp,baseCost:data.cost};}
    /* 컴퓨터 비용 = 이번 턴 상대 최대 마나(발동 시점). 오라 공명이면 −2 */
