    function selectUnit(unit,automatic=false){ if(battlePhase!=='setup'&&!automatic)return;if(unit.classList.contains('exhausted')){ writeLog('<strong>'+unit.querySelector('h4').textContent+'</strong>은(는) 이번 턴에 이미 공격했습니다.'); return; } sfx('ui-select');document.querySelectorAll('.unit').forEach(u=>u.classList.remove('selected')); unit.classList.add('selected'); document.querySelector('#hand-guide').textContent=automatic?'내 하수인 전투 처리 중':unit.querySelector('h4').textContent+(unit.dataset.ultimateSpent==='true'?' 선택됨 · 소진자는 상대 소환사를 우선 공격(상대 소진자가 있으면 그쪽)':' 선택됨 · 상대 왼쪽 카드부터 공격'); }
    function attack(target,automatic=false){ if(battlePhase!=='setup'&&!automatic)return;const selected=document.querySelector('.unit.selected'); if(!selected){ writeLog('먼저 내 소환수 카드를 선택하세요.'); return; } if(selected.closest('.lane')===target.closest('.lane')){ selectUnit(target,automatic); return; }const enemyLane=document.querySelector('.arena .lane:first-child'),priority=enemyLane.querySelector(':scope > .unit[data-ultimate-aggro="true"]:not([data-destroyed="true"])')||enemyLane.querySelector(':scope > .unit[data-taunt="true"]:not([data-destroyed="true"])')||enemyLane.querySelector(':scope > .unit:not([data-destroyed="true"])');if(!priority||selected.dataset.ultimateSpent==='true'){attackFace(document.querySelector('.duel-hud .enemy'),automatic);return;}/* 소진자는 상대 하수인이나 상대 소진자(전역 도발)가 있어도 소환사를 공격한다 (2026-11-08 PM 확정) */const sweep=/^sweep-(\d+)$/.exec(selected.dataset.effect||'');if(sweep){const ratio=Number(sweep[1])/100,sweepTargets=[...document.querySelectorAll('.arena .lane:first-child > .unit:not([data-destroyed="true"])')];sweepTargets.forEach((enemy,i)=>setTimeout(()=>{if(!selected.isConnected||!enemy.isConnected||enemy.dataset.destroyed==='true')return;resolveDuel(selected,enemy,{playerAttack:i===0,ratio});},i*combatMs(260)));writeLog('<strong>'+selected.querySelector('h4').textContent+'</strong>의 기본 공격이 적 하수인 '+sweepTargets.length+'장 전체를 휩쓸었습니다. (공격력의 '+sweep[1]+'%)');}else{if(priority.dataset.ultimateAggro==='true')showUltimateAggroIntercept(priority);else if(target!==priority&&!automatic)writeLog('공격 대상은 상대 전장의 가장 왼쪽 카드로 자동 지정됩니다.');resolveDuel(selected,priority,{playerAttack:true});}selected.classList.remove('selected','attacking');if(selected.isConnected)selected.classList.add('exhausted');selected.dataset.attacked='1';document.querySelector('#hand-guide').textContent=automatic?'내 하수인 전투 처리 중':'내 카드 순서는 준비 턴에 드래그해 변경할 수 있습니다'; }
    function attackFace(target,automatic=false){ if(battlePhase!=='setup'&&!automatic)return;const selected=document.querySelector('.unit.selected'),enemyHud=target?.closest?.('.enemy')||document.querySelector('.duel-hud .enemy'); if(!selected){ writeLog('먼저 내 하수인 카드를 선택하세요.'); return; } if(!selected.closest('.summon-zone')){writeLog('내 하수인만 공격할 수 있습니다.');return;} if(enemyHud){ const defenders=[...document.querySelectorAll('.lane:nth-child(1) .unit:not([data-destroyed="true"])')];if(defenders.length&&selected.dataset.ultimateSpent!=='true'){const front=defenders.find(u=>u.dataset.ultimateAggro==='true')||defenders.find(u=>u.dataset.taunt==='true')||defenders[0];writeLog('<strong>'+front.querySelector('h4').textContent+'</strong>이 전장을 지키고 있어 상대 소환사를 직접 공격할 수 없습니다. 맨 왼쪽 하수인을 공격합니다.');attack(front,automatic);return;} const baseAtk=Number(selected.querySelector('.stats span').textContent.replace(/[^0-9]/g,''))||0,element=getElement(selected),field=getFieldBonus(selected),chainBonus=registerChain(element),damage=baseAtk<=0?0:baseAtk+field.bonus+chainBonus,note=[field.label,chainBonus?'연쇄 +'+chainBonus:''].filter(Boolean).join(' · '),hero=enemyHud.querySelector('.avatar'),healthBar=enemyHud.querySelector('.health i'),enemyTrap=triggerEnemyTrap('enemy_hero_attacked',{attacker:selected,damage});if(enemyTrap.prevented||enemyAbsoluteDefense){if(!enemyTrap.prevented)showGuardedHeroAttack(selected,hero,damage);if(!enemyTrap.logged)writeLog(enemyTrap.prevented?'<strong>상대 함정</strong>이 소환사 공격을 막았습니다.':'<strong>상대 절대방어</strong>가 소환사 공격을 막았습니다.');selected.classList.remove('selected','attacking');selected.classList.add('exhausted');return;}fieldAttack(selected,hero,{label:damage+' 피해',onImpact:()=>{impact(hero,damage,element);enemyHp=Math.max(0,enemyHp-damage);healthBar.style.width=(enemyHp/HERO_MAX_HP*100)+'%';healthBar.parentElement.setAttribute('aria-label','상대 체력 '+enemyHp+' / '+HERO_MAX_HP);writeLog('<strong>'+selected.querySelector('h4').textContent+'</strong>이 상대 소환사를 직접 공격해 '+damage+' 피해를 입혔습니다. 남은 체력 '+enemyHp+(note?' ('+note+')':'') );if(enemyHp<=0)finish(true,'상대 소환사의 체력을 0으로 만들었습니다.');}});selected.classList.remove('selected','attacking');selected.classList.add('exhausted'); } }
    function framePaths(element){ if(element==='fire')return Array.from({length:35},(_,i)=>'assets/vfx/fire/fx2_swordFire/spell_decap_1_zoomblur_'+(i+1)+'.webp'); if(element==='earth')return Array.from({length:19},(_,i)=>'assets/vfx/earth/fx10_blackExplosion/smoke_black_1_19_'+(i+1)+'.webp'); return Array.from({length:22},(_,i)=>'assets/vfx/water/fx1_blue_topEffect/spell_bluetop_1_'+(i+1)+'.webp'); }
    const impactPalette={'black-flame':'#c4161f',fire:'#ff6b3d',water:'#52d9ff',ice:'#a6ecff',earth:'#d4a15d',wind:'#72f2bd',thunder:'#ffe14d',neutral:'#dfe6f2'};/* neutral=금속 오라(은빛) — 없으면 불빛으로 대체되던 문제 */
    function addCombatLayer(className,x,y,color,life=800){ const node=document.createElement('i'); node.className=className; node.style.left=x+'px'; node.style.top=y+'px'; node.style.setProperty('--fx-color',color); document.body.appendChild(node);slowCombatAnimations(node);setTimeout(()=>node.remove(),combatMs(life));return node; }
    function heroHealthImpact(target,damage){const owner=target.closest('.enemy,.player');if(!owner)return;const enemy=owner.classList.contains('enemy'),bar=owner.querySelector('.health'),fill=bar?.querySelector('i'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
      document.querySelectorAll('.hero-edge-flash').forEach(node=>node.remove());const edge=document.createElement('div');edge.className='hero-edge-flash '+(enemy?'enemy-side':'player-side');edge.style.setProperty('--edge-x',enemy?'0%':'100%');document.body.appendChild(edge);setTimeout(()=>edge.remove(),1400);
      if(!bar)return;/* 체력바 흔들림: CSS 애니메이션(체력바 맥동)을 덮어쓰지 않도록 translate 속성을 Web Animations로 흔든다 */
      if(!reduced)bar.animate([{scale:'1'},{scale:'1.12',offset:.12},{scale:'1.08',offset:.4},{scale:'1'}],{duration:620,easing:'cubic-bezier(.2,.8,.3,1)'});/* 흔들림과 함께 살짝 확대됐다가 원래 크기로 */
      if(!reduced)bar.animate([{translate:'0 0',filter:'brightness(1)'},{translate:'-12.6px 1.8px',filter:'brightness(1.8)',offset:.08},{translate:'11.7px -1.8px',offset:.18},{translate:'-9.9px 0.9px',offset:.28},{translate:'8.1px -0.9px',filter:'brightness(1.3)',offset:.4},{translate:'-6.3px 0.9px',offset:.52},{translate:'4.5px 0',offset:.64},{translate:'-2.7px 0',offset:.76},{translate:'1.8px 0',offset:.88},{translate:'0 0',filter:'brightness(1)'}],{duration:620,easing:'ease-out'});
      const br=bar.getBoundingClientRect(),fr=fill?fill.getBoundingClientRect():br,pop=document.createElement('div');pop.className='hp-damage-pop';pop.textContent='−'+damage;pop.style.setProperty('--pop-scale',(1.3+Math.min(damage,30)*.01).toFixed(2));/* 소환사 피해는 카드 피해 숫자의 1.3~1.6배 — 총체력이 더 치명적이므로 항상 더 크게 */pop.style.left=Math.max(br.left+24,Math.min(br.right-24,fr.right))+'px';document.body.appendChild(pop);{const size=parseFloat(getComputedStyle(pop).fontSize),below=br.bottom+size*1.1;/* 큰 숫자가 위로 떠오르다 화면 위로 잘리지 않게 크기만큼 아래에서 시작한다. 다만 체력바가 화면 아래쪽(하단 소환사 줄)이라 아래 공간이 모자라면 체력바 위에서 떠오르게 해 화면 밖으로 나가지 않게 한다 (2026-11-08) */pop.style.top=(below<=innerHeight-6?below:br.top-6)+'px';}setTimeout(()=>pop.remove(),1350);}
